# Explicit formula dictionaries support formula sheets and clear numerical units.
def formula(expression,variables,units,assumptions):return dict(expression=expression,variables=variables,units=units,assumptions=assumptions)
FP=formula('c2=(x²+y²−L1²−L2²)/(2L1L2); s2=±sqrt(1−c2²); θ2=atan2(s2,c2); θ1=atan2(y,x)−atan2(L2*s2,L1+L2*c2); θ3=φ−θ1−θ2',{'L1,L2':'positive planar link lengths','x,y':'desired frame3 position','φ':'desired planar orientation','θ1,θ2,θ3':'joint angles','c2,s2':'cosine and sine of elbow angle'},{'L1,L2,x,y':'common length unit as stated in the question','φ,θ1,θ2,θ3':'degrees in degree examples; otherwise radians','c2,s2':'dimensionless'},PLANAR+['Generic atan2 shoulder formula excludes the equal-link zero-radius degenerate family.'])
FF=formula('x=L1 cosθ1+L2 cos(θ1+θ2); y=L1 sinθ1+L2 sin(θ1+θ2); φ=θ1+θ2+θ3',{'L1,L2':'link lengths','x,y':'frame3 origin','θ1,θ2,θ3':'joint angles','φ':'frame3 orientation'},{'L1,L2,x,y':'common length unit','angles':'degrees for the examples'},PLANAR)
FD=formula('ul=(v−dω)/r; ur=(v+dω)/r; ω=r(ur−ul)/(2d); xdot=[r(ul+ur)/2]cosφ; ydot=[r(ul+ur)/2]sinφ',{'r':'wheel radius','d':'half wheel separation','v':'body-forward velocity','ω':'yaw rate','ul,ur':'wheel angular rates','φ':'world heading','xdot,ydot':'world translational rates'},{'r,d':'m','v,xdot,ydot':'m/s','ω,ul,ur':'rad/s','φ':'angle,degree values explicitly converted for trig'},DRIVE)
for q in Q:
 if q['type']=='numerical':
  p=int(q['id'].split('-P')[1].split('-')[0])
  if p==275:q['solution']['formulas']=[formula('|L1−L2|≤ρ≤L1+L2',{'ρ':'target radius','L1,L2':'positive link lengths'},{'ρ,L1,L2':'m'},['Unrestricted planar2R position model.'])]
  elif p==278:q['solution']['formulas']=[formula('f(αx)=αf(x); f(x)=2x',{'α':'scalar multiplier','x':'test input','f':'test linear map'},{'all':'dimensionless'},['Explicit repair of the printed homogeneity typo.'])]
  elif p==281:q['solution']['formulas']=[formula('sin(180°−a)=sin a; cos(180°−a)=−cos a',{'a':'reference angle'},{'a':'degrees','trig values':'dimensionless'},['a=30° in the example.'])]
  elif p==282:q['solution']['formulas']=[FF]
  elif p in(283,284,285):q['solution']['formulas']=[FP,FF]
  elif p==287:q['solution']['formulas']=[formula('ρ=sqrt(x²+y²); β=atan2(y,x); ψ=acos((ρ²+L1²−L2²)/(2L1ρ))',{'ρ':'target radius','β':'target bearing','ψ':'shoulder triangle offset','L1,L2':'link lengths','x,y':'target coordinates'},{'ρ,L1,L2,x,y':'common length unit','β,ψ':'degrees in example'},['Reachable target withρ>0;principalψ in[0°,180°].'])]
  elif p in(289,292):q['solution']['formulas']=[FD]
  elif p==291:q['solution']['formulas']=[formula('J+=(J^T J)^−1 J^T for full column rank; J+=J^T(J J^T)^−1 for full row rank; u=J+b',{'J':'given linear map','b':'desired output','u':'input selected by pseudoinverse'},{'matrix examples':'dimensionless','robot example':'rate coordinates as explicitly stated'},['Use only the matching full-rank shortcut and explicit least-squares/minimum-norm interpretation.'])]
 # Precise page-level locator/type rather than trusting extracted hidden equation text.
 for cite in q['citations']:
  p=cite['physicalPage'];cite['locator']=f'Printed slide {p-268}: '+{272:'introductory two-step task and labeled frame figure',273:'six-transform product and pose-constraint counting bullets',274:'three challenge bullets',275:'workspace definitions and equal/unequal planar2R examples',276:'solution-selection bullets and obstacle/elbow figure',277:'6R table: condition and maximum-solution columns',278:'displayed definition row relevant to the question, including literal typo where stated',279:'nonlinear-equation and algorithmic-solvability discussion',280:'solution-method classification and sufficient intersection condition',281:'spherical-wrist labels, Pieper reference and lookup-table bullets',282:'planar3R homogeneous matrix, DH table and pose equations',283:'squared-position derivation, cosine domain and signed-sine/atan2 equations',284:'k1/k2 definitions, polar triangle and shoulder derivation; middle printed line preserved',285:'origin exception and joint-angle-sum equation',286:'law-of-cosines derivation and alternate-elbow figure',287:'reachability/branch bullets and β/cosψ equations',288:'ψ interval, signed shoulder branch rule, angle sum and inconsistent last line',289:'wheel geometry diagram and3×2 velocity Jacobian',290:'inverse-task text, non-square inverse notation and flow-arrow variable labels',291:'full-rank tall/wide pseudoinverse formulas',292:'body-speed sum/difference and individual wheel-rate formulas',293:'four summary bullets, including numerical singularity handling'}[p]
  if q['type']!='diagram' and p in range(282,293):cite['kind']='equation'
