# Author verification, explicitly not independent answer review.
import numpy as np
import sympy as sp
checks=[]
def check(key,passed,detail):
 checks.append(dict(id=key,passed=bool(passed),verificationKind='author_symbolic_or_numerical_check',detail=detail))
 if not passed:raise AssertionError(key)
a,b,t1,t2=sp.symbols('a b t1 t2',real=True)
x=a*sp.cos(t1)+b*sp.cos(t1+t2);y=a*sp.sin(t1)+b*sp.sin(t1+t2)
check('planar-squared-radius-identity',sp.trigsimp(sp.expand_trig(x*x+y*y-a*a-b*b-2*a*b*sp.cos(t2)))==0,'Symbolic expansion equals0 for all real angles/lengths.')
k1=a+b*sp.cos(t2);k2=b*sp.sin(t2)
check('planar-k-vector-expansion',sp.trigsimp(sp.expand_trig(x-(k1*sp.cos(t1)-k2*sp.sin(t1))))==0 and sp.trigsimp(sp.expand_trig(y-(k1*sp.sin(t1)+k2*sp.cos(t1))))==0,'Both k1/k2 equations exactly match the forward equations.')
g,theta=sp.symbols('g theta',real=True)
check('corrected-cosine-addition',sp.trigsimp(sp.cos(g)*sp.cos(theta)-sp.sin(g)*sp.sin(theta)-sp.cos(g+theta))==0,'Corrected final sin(theta1) factor yields exact identity.')
wrong=sp.cos(g)*sp.cos(theta)-sp.sin(g)*sp.cos(theta)
check('as-printed-middle-line-counterexample',sp.simplify(wrong.subs({g:sp.pi/2,theta:0}))==-1 and sp.cos(sp.pi/2)==0,'At gamma=90°,theta1=0°,printed x/r=−1 but correct x/r=0.')
check('as-printed-theta3-counterexample',0-0+90==90 and (0+90+90)%360!=0 and (0+90-90)%360==0,'For phi=0°,theta1=0°,theta2=90°,printed theta3=90° gives180°,corrected−90° gives0°.')
check('triangle-law-cosines-sign',sp.trigsimp(sp.cos(sp.pi+t2)+sp.cos(t2))==0,'cos(pi+theta2)=−cos(theta2),matching the joint-angle convention.')
check('source-homogeneity-counterexample',2*(3*1)==6 and 3*1==3 and 3*(2*1)==6,'f(x)=2x,alpha3,x1:printed right3 differs from left6;repaired right6.')
check('unit-circle-not-linear-subspace',1**2+0**2==1 and 2**2+0**2!=1,'(1,0)lies on the unit circle but its scalar multiple(2,0)does not.')
check('reachability-inner-outer',((.5**2-2**2-1**2)/(2*2*1)==-1.1875) and ((3.5**2-2**2-1**2)/4==1.8125),'Too-close and too-far cases both violate|c2|<=1,with opposite signs.')
def fk(L1,L2,angles):
 a,b,c=angles;return np.array([L1*np.cos(a)+L2*np.cos(a+b),L1*np.sin(a)+L2*np.sin(a+b),a+b+c])
def ik(L1,L2,x,y,phi):
 c=(x*x+y*y-L1*L1-L2*L2)/(2*L1*L2)
 if c < -1-1e-12 or c>1+1e-12:return []
 c=np.clip(c,-1,1);out=[]
 for s in [np.sqrt(max(0,1-c*c)),-np.sqrt(max(0,1-c*c))]:
  t2=np.arctan2(s,c);t1=np.arctan2(y,x)-np.arctan2(L2*s,L1+L2*c);out.append([t1,t2,phi-t1-t2])
 return out
check('unit-target-two-branches',np.allclose(np.degrees(ik(1,1,1,1,0)),[[0,90,-90],[90,-90,0]]),'Exact expected branch triples,checked numerically at1e-8 default absolute tolerance.')
rng=np.random.default_rng(20261019);maxerr=0.;n=0
for _ in range(250):
 L1,L2=rng.uniform(.1,5,2);angles=rng.uniform(-np.pi,np.pi,3);target=fk(L1,L2,angles)
 for sol in ik(L1,L2,*target):
  maxerr=max(maxerr,float(np.max(np.abs(fk(L1,L2,sol)-target))));n+=1
check('random-planar-roundtrips',n==500 and maxerr<1e-10,dict(seed=20261019,samples=250,branchesChecked=n,maxAbsolutePoseResidual=maxerr))
check('quadrant-shoulder-example',np.isclose(np.degrees(ik(1,1,-1,1,0)[0][0]),90),'Target(-1,1),positive elbow yields shoulder90°,not−90°.')
check('workspace-boundary-elbows',np.isclose(np.degrees(ik(2,1,3,0,0)[0][1]),0) and np.isclose(np.degrees(ik(2,1,1,0,0)[0][1]),180),'Outer radius3 gives0°,inner radius1 gives180°;branches merge modulo360°.')
originerrs=[np.linalg.norm(fk(1,1,[v,np.pi,.3-v-np.pi])-[0,0,.3]) for v in np.linspace(-4,4,21)]
check('origin-continuum',max(originerrs)<1e-14,dict(samples=21,maxResidual=max(originerrs),family='theta2=pi;theta1 free;theta3=phi-theta1-pi'))
check('geometric-offset-example',np.isclose(np.degrees(np.arccos((2+1-1)/(2*np.sqrt(2)))),45),'Unit-link target(1,1):beta=psi=45°.')
check('quarter-wave-values',np.isclose(np.sin(np.deg2rad(150)),.5) and np.isclose(np.cos(np.deg2rad(150)),-np.sqrt(3)/2),'sin150°=.5;cos150°=−sqrt(3)/2.')
r,d,phi=sp.symbols('r d phi',positive=True,real=True)
J=sp.Matrix([[-r/(2*d),r/(2*d)],[r*sp.cos(phi)/2,r*sp.cos(phi)/2],[r*sp.sin(phi)/2,r*sp.sin(phi)/2]])
JP=sp.Matrix([[-d/r,sp.cos(phi)/r,sp.sin(phi)/r],[d/r,sp.cos(phi)/r,sp.sin(phi)/r]])
check('differential-gram-determinant',sp.trigsimp((J.T*J).det()-r**4/(4*d**2))==0,'det(J^T J)=r^4/(4d²)>0 forr,d>0,independent ofheading.')
check('differential-pseudoinverse-derived',all(sp.simplify(sp.trigsimp(v))==0 for v in ((J.T*J)*JP-J.T)),'JP satisfies the full-rank normal equation exactly;Gram determinant positive.')
check('differential-left-identity',all(sp.trigsimp(v)==0 for v in JP*J-sp.eye(2)),'J+J=I2 exactly.')
projection=sp.Matrix([[1,0,0],[0,sp.cos(phi)**2,sp.sin(phi)*sp.cos(phi)],[0,sp.sin(phi)*sp.cos(phi),sp.sin(phi)**2]])
check('differential-output-projection',all(sp.trigsimp(v)==0 for v in J*JP-projection),'JJ+ fixes yaw and projects translation onto heading;notI3.')
Jn=np.array(J.subs({r:.1,d:.2,phi:sp.pi/2})).astype(float)
check('heading-90-forward-example',np.allclose(Jn@np.array([3,7]),[1,0,.5]) and np.linalg.matrix_rank(Jn)==2,'Heading90° gives[omega,xdot,ydot]=[1,0,.5]andrank2.')
check('wheel-inverse-numeric',np.allclose([(.5-.2)/.1,(.5+.2)/.1],[3,7]) and np.allclose([(-.2)/.1,.2/.1],[-2,2]) and np.isclose(-.4/.1,-4),'Full-track.4→half-track.2;turn(3,7),spin(−2,2),backward(−4,−4).')
J0=np.array(J.subs({r:.1,d:.2,phi:0})).astype(float);target=np.array([0,0,1.]);u=np.linalg.pinv(J0)@target
check('incompatible-lateral-target',np.allclose(u,[0,0]) and np.allclose(target-J0@u,[0,0,1]),dict(input=u.tolist(),residual=(target-J0@u).tolist()))
tall=np.array([[1,0],[0,1],[0,0]]);wide=np.array([[1,1]])
check('tall-least-squares-example',np.allclose(np.linalg.pinv(tall)@[2,3,4],[2,3]),'Input[2,3],residual[0,0,4].')
check('wide-minimum-norm-example',np.allclose(np.linalg.pinv(wide)@[2],[1,1]),'Minimum-norm exact input[1,1].')
N=100;maxdrive=0.
for _ in range(N):
 rr,dd=rng.uniform(.01,2,2);ph=rng.uniform(-np.pi,np.pi);rates=rng.uniform(-20,20,2)
 jj=np.array([[-rr/(2*dd),rr/(2*dd)],[rr*np.cos(ph)/2,rr*np.cos(ph)/2],[rr*np.sin(ph)/2,rr*np.sin(ph)/2]])
 jp=np.array([[-dd/rr,np.cos(ph)/rr,np.sin(ph)/rr],[dd/rr,np.cos(ph)/rr,np.sin(ph)/rr]])
 maxdrive=max(maxdrive,float(np.max(np.abs(jp@jj@rates-rates))),float(np.max(np.abs(jp-np.linalg.pinv(jj)))))
check('random-drive-pseudoinverse-roundtrips',maxdrive<1e-10,dict(seed=20261019,samples=N,maxError=maxdrive))
